def assign_existing_owners(apps, schema_editor):
    """Existing companies are owned by their creator, or else their longest-serving active admin."""
    Company = apps.get_model("companies", "Company")
    Membership = apps.get_model("companies", "CompanyMembership")
    Grant = apps.get_model("companies", "CompanyRoleGrant")
    for company in Company.objects.filter(owner__isnull=True):
        admins = Grant.objects.filter(
            membership__company=company,
            membership__access_state="active",
            membership__ended_at__isnull=True,
            role_code="company_admin",
            revoked_at__isnull=True,
        )
        creator = company.created_by_id and (
            admins.filter(membership__person__identity_user_id=company.created_by_id).first()
        )
        grant = creator or admins.order_by("granted_at", "id").first()
        if grant:
            company.owner = Membership.objects.get(pk=grant.membership_id)
            company.save(update_fields=["owner"])


